/**
 * @title PolishedDiamond
 * @dev This contract represents the transactions involves with the diamond lifecycle.
 * It links polished diamonds to their original rough diamond
 * and manages ownership and transfer of assets.
 *
 * This contract ensures:
 * - Only certified rough diamonds can be used
 * - Ownership is tracked immutably
 * - Full traceability is maintained
 */
pragma solidity ^0.8.0;


// Interface to connect contracts
interface IStakeholder {

    // 🔹 Core checks
    function isRegistered(address _addr) external view returns (bool);

    function isMiner(address _addr) external view returns (bool);

    function isConsumer(address _addr) external view returns (bool);

    function isCertifier(address _addr) external view returns (bool);

    function isGrader(address _addr) external view returns (bool);
}

contract PolishedDiamond {

    enum DiamondState {
        Rough,
        Certified,
        Polished
    }

    struct Diamond {
        uint id;
        uint parentId; // 0 = rough diamond

        address owner;

        // Origin (set by miner)
        string origin;

        // Lifecycle state
        DiamondState state;

        // Certification (ONLY for rough)
        address certifier;

        // Grading / polishing
        address grader;
        string gradingReport;
    }

    mapping(uint => Diamond) public diamonds;
    uint[] public diamondIds;


    IStakeholder public stakeholderContract;

    constructor(address _stakeholderAddress) {
    stakeholderContract = IStakeholder(_stakeholderAddress);
    }

    // Contract Stakeholder Modifiers

    

    // Miner Rights

    function mintRoughDiamond(uint _id, string memory _origin) public {

    require(
        stakeholderContract.isMiner(msg.sender),
        "Only miners can mint rough diamonds"
    );

    require(diamonds[_id].id == 0, "Diamond already exists");

    diamonds[_id] = Diamond({
        id: _id,
        parentId: 0,
        owner: msg.sender,
        origin: _origin,
        state: DiamondState.Rough,
        certifier: address(0),
        grader: address(0),
        gradingReport: ""
    });

    diamondIds.push(_id);
}










    // KIMBERLEY CERTIFIER LOGIC








    // 








    // 
}

